def validateCoupons(code, businessLine, isActive):
    order = {"electronics": 0, "grocery": 1, "pharmacy": 2, "restaurant": 3}

    def valid_code(s):
        if not s:
            return False
        for ch in s:
            if not ((ch.isascii() and ch.isalnum()) or ch == "_"):
                return False
        return True

    valid = []
    for c, b, a in zip(code, businessLine, isActive):
        if a and b in order and valid_code(c):
            valid.append((order[b], c))
    valid.sort()
    return [c for _, c in valid]
